const LocalNotice = ({ children }) => <p className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs leading-5 text-amber-800 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-200">{children}</p>;
const inputClass = 'mt-1 min-h-11 w-full rounded-xl border border-gray-200 bg-transparent px-3 text-sm dark:border-gh-border';
const field = (label, value, onChange, type = 'text', readOnly = false) => <label className="block text-xs font-semibold">{label}<input type={type} value={value ?? ''} readOnly={readOnly} onChange={(event) => onChange?.(event.target.value)} className={inputClass} /></label>;
const downloadCsv = (name, headers, rows) => { const quote = (value) => `"${String(value ?? '').replaceAll('"', '""')}"`; const href = `data:text/csv;charset=utf-8,${encodeURIComponent([headers, ...rows].map((row) => row.map(quote).join(',')).join('\n'))}`; const link = document.createElement('a'); link.href = href; link.download = name; document.body.appendChild(link); link.click(); link.remove(); };

function PhaseDetailContent({ phase }) {
    const activities = phase?.activities || [];
    const progress = activities.length ? Math.round(activities.reduce((sum, task) => sum + Number(task.progress || 0), 0) / activities.length) : 0;
    const starts = activities.map((task) => task.start).filter(Boolean).sort(); const ends = activities.map((task) => task.end).filter(Boolean).sort();
    const highPriority = activities.filter((task) => task.critical).length; const behindPlan = activities.filter((task) => dateDiff(task.end, task.origEnd) > 0).length;
    return <div data-phase-detail className="space-y-4"><div className="rounded-2xl border p-4 dark:border-gh-border" style={{ borderLeftWidth: 4, borderLeftColor: phase.color }}><div className="flex items-center gap-3"><span className="text-2xl" aria-hidden="true">{phase.icon}</span><div className="min-w-0"><h3 className="text-base font-black">{phase.name}</h3><p className="text-xs text-gray-500">Read-only phase summary</p></div></div></div><div className="grid grid-cols-2 gap-2"><MobileStatCard label="Progress" value={`${progress}%`} tone="green"/><MobileStatCard label="Completed" value={`${activities.filter((task) => Number(task.progress) >= 100).length}/${activities.length}`}/><MobileStatCard label="High priority" value={highPriority} tone="red"/><MobileStatCard label="Behind plan" value={behindPlan} tone={behindPlan ? 'red' : 'green'}/></div><MobileFormSection title="Phase timeline"><dl className="space-y-2 text-sm"><div className="flex justify-between gap-3"><dt className="text-gray-500">Phase start</dt><dd className="font-semibold">{starts[0] || '—'}</dd></div><div className="flex justify-between gap-3"><dt className="text-gray-500">Phase end</dt><dd className="font-semibold">{ends.at(-1) || '—'}</dd></div></dl></MobileFormSection><MobileFormSection title={`Tasks (${activities.length})`}><div className="space-y-2">{activities.length ? activities.map((task) => <div key={task.id} className="rounded-xl bg-gray-50 p-3 dark:bg-gh-hover"><div className="flex justify-between gap-2"><b className="text-xs">{task.name}</b><span className="text-xs font-bold">{task.progress}%</span></div><div className="mt-2 h-1.5 rounded bg-gray-200 dark:bg-gray-700"><span className="block h-full rounded" style={{ width: `${task.progress}%`, backgroundColor: phase.color }}/></div><p className="mt-2 text-[11px] text-gray-500">{task.start || '—'} → {task.end || '—'}</p></div>) : <p className="text-sm text-gray-500">No activities in this phase.</p>}</div></MobileFormSection></div>;
}

function ScheduleWorkspace({ projectId, canWrite, aiService }) {
    const [phases, setPhases] = useState(() => clone(SOURCE_PHASES)); const [filter, setFilter] = useState('all'); const [original, setOriginal] = useState(true); const [expanded, setExpanded] = useState({}); const [phaseDetail, setPhaseDetail] = useState(null); const [phaseEditor, setPhaseEditor] = useState(null); const [taskEditor, setTaskEditor] = useState(null); const [confirm, setConfirm] = useState(null); const [insights, setInsights] = useState(null); const [aiState, setAiState] = useState('idle'); const [aiError, setAiError] = useState(''); const guard = useRef(createM9RequestGuard());
    useEffect(() => { guard.current.invalidate(projectId); setPhases(clone(SOURCE_PHASES)); setFilter('all'); setExpanded({}); setPhaseDetail(null); setPhaseEditor(null); setTaskEditor(null); setConfirm(null); setInsights(null); setAiState('idle'); }, [projectId]);
    const visible = filter === 'all' ? phases : phases.filter((phase) => phase.id === filter); const tasks = phases.flatMap((phase) => phase.activities); const progress = tasks.length ? Math.round(tasks.reduce((sum, task) => sum + Number(task.progress || 0), 0) / tasks.length) : 0;
    const savePhase = (event) => { event.preventDefault(); if (!canWrite || !phaseEditor?.name?.trim()) return; setPhases((current) => phaseEditor.id ? current.map((phase) => phase.id === phaseEditor.id ? { ...phase, ...phaseEditor } : phase) : [...current, { ...phaseEditor, id: makeLocalId('phase'), activities: [] }]); setPhaseEditor(null); };
    const saveTask = (event) => { event.preventDefault(); if (!canWrite || !taskEditor?.task?.name?.trim()) return; setPhases((current) => current.map((phase) => phase.id === taskEditor.phaseId ? { ...phase, activities: taskEditor.task.id ? phase.activities.map((task) => task.id === taskEditor.task.id ? taskEditor.task : task) : [...phase.activities, { ...taskEditor.task, id: makeLocalId('task'), origStart: taskEditor.task.start, origEnd: taskEditor.task.end }] } : phase)); setTaskEditor(null); };
    const remove = () => { if (confirm?.type === 'phase') { setPhases((current) => current.filter((phase) => phase.id !== confirm.id)); setPhaseDetail((current) => current?.id === confirm.id ? null : current); } else if (confirm?.type === 'task') setPhases((current) => current.map((phase) => ({ ...phase, activities: phase.activities.filter((task) => task.id !== confirm.id) }))); setConfirm(null); };
    const move = (index, direction) => { if (!canWrite) return; setPhases((current) => { const next = [...current]; const target = index + direction; if (target < 0 || target >= next.length) return current; [next[index], next[target]] = [next[target], next[index]]; return next; }); };
    const loadInsights = async () => { const token = guard.current.begin(projectId); setAiState('loading'); setAiError(''); setInsights(null); try { const response = await (aiService?.scheduleInsights ? aiService.scheduleInsights({ phases, macro: false }) : api.post('/ai/schedule-insights', { phases, macro: false }).then((result) => result.data)); if (!guard.current.isCurrent(token, projectId)) return; setInsights(response?.data?.insights || response?.insights || []); setAiState('success'); } catch (error) { if (!guard.current.isCurrent(token, projectId)) return; setAiError(errorMessage(error, 'AI schedule insights could not be loaded.')); setAiState('error'); } };
    return <div data-m9-view="project-planning" className="space-y-3 px-4 pb-28"><MobilePageHeader title="Project Planning" subtitle="Touch-friendly local schedule workspace" /><LocalNotice>Schedule edits stay in this browser view and are not saved to the ERP. The source schedule uses 15 Aug 2026 as its reference date.</LocalNotice><div className="grid grid-cols-2 gap-2"><MobileStatCard label="Phases" value={phases.length} icon={BarChart3}/><MobileStatCard label="Average progress" value={`${progress}%`} icon={CalendarDays} tone="green"/><MobileStatCard label="Activities" value={tasks.length}/><MobileStatCard label="Critical" value={tasks.filter((task) => task.critical).length} tone="red"/></div><div className="flex gap-2"><MobileSelect label="Phase filter" value={filter} onChange={(event) => setFilter(event.target.value)} options={[{ value: 'all', label: 'All phases' }, ...phases.map((phase) => ({ value: phase.id, label: phase.name }))]} /><label className="mt-6 flex min-h-11 items-center gap-2 rounded-xl border border-gray-200 px-3 text-xs font-semibold dark:border-gh-border"><input type="checkbox" checked={original} onChange={(event) => setOriginal(event.target.checked)} />Original plan</label></div><div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => downloadCsv('Project_Schedule.csv', ['Phase','Activity','Start','End','Original Start','Original End','Progress','Critical','Milestone'], phases.flatMap((phase) => phase.activities.map((task) => [phase.name, task.name, task.start, task.end, task.origStart, task.origEnd, task.progress, task.critical, task.milestone])))} className="min-h-11 rounded-xl border border-gray-200 text-xs font-bold dark:border-gh-border"><Download size={15} className="mr-1 inline"/>Export CSV</button><button type="button" onClick={loadInsights} className="min-h-11 rounded-xl bg-violet-600 text-xs font-bold text-white"><Sparkles size={15} className="mr-1 inline"/>AI insights</button></div>{visible.map((phase, index) => <MobileCard key={phase.id} data-phase-id={phase.id}><div className="flex items-start gap-2"><button type="button" aria-label={`${expanded[phase.id] === false ? 'Expand' : 'Collapse'} ${phase.name}`} onClick={() => setExpanded((current) => ({ ...current, [phase.id]: current[phase.id] === false }))} className="min-h-11 min-w-11 rounded-xl border text-lg dark:border-gh-border">{expanded[phase.id] === false ? '›' : '⌄'}</button><button type="button" aria-label={`View ${phase.name} details`} onClick={() => setPhaseDetail(clone(phase))} className="flex min-h-11 min-w-0 flex-1 items-start gap-3 text-left"><span className="text-xl">{phase.icon}</span><span className="min-w-0 flex-1"><span className="block text-sm font-black">{phase.name}</span><span className="block text-xs text-gray-500">{phase.activities.length} activities</span></span></button>{canWrite && <div className="flex gap-1"><button type="button" aria-label={`Move ${phase.name} up`} disabled={index === 0} onClick={() => move(phases.indexOf(phase), -1)} className="min-h-11 min-w-11 rounded-xl border dark:border-gh-border">↑</button><button type="button" aria-label={`Move ${phase.name} down`} disabled={phases.indexOf(phase) === phases.length - 1} onClick={() => move(phases.indexOf(phase), 1)} className="min-h-11 min-w-11 rounded-xl border dark:border-gh-border">↓</button></div>}</div>{expanded[phase.id] !== false && <div className="mt-3 space-y-2">{phase.activities.map((task) => { const variance = dateDiff(task.end, task.origEnd); return <button type="button" key={task.id} onClick={() => setTaskEditor({ phaseId: phase.id, task: clone(task) })} className="w-full rounded-xl bg-gray-50 p-3 text-left dark:bg-gh-hover"><div className="flex justify-between gap-2"><b className="text-xs">{task.name}</b><span className="text-[10px] font-bold">{task.progress}%</span></div><div className="mt-2 h-1.5 rounded bg-gray-200 dark:bg-gray-700"><span className="block h-full rounded bg-blue-600" style={{ width: `${task.progress}%` }}/></div><p className="mt-2 text-[11px] text-gray-500">{task.start} → {task.end}{original ? ` · original ${task.origStart} → ${task.origEnd}` : ''}</p><p className={`mt-1 text-[10px] font-bold ${variance > 0 ? 'text-red-600' : 'text-emerald-600'}`}>{variance > 0 ? `${variance} day delay` : 'On or ahead of original finish'}{task.critical ? ' · High priority' : ''}{task.milestone ? ' · Key deliverable' : ''}</p></button>; })}</div>}{canWrite && <div className="mt-3 grid grid-cols-3 gap-2"><button type="button" onClick={() => setTaskEditor({ phaseId: phase.id, task: { name: '', start: '', end: '', progress: 0, critical: false, milestone: false } })} className="min-h-11 rounded-xl border text-xs font-bold dark:border-gh-border">Add task</button><button type="button" onClick={() => setPhaseEditor(clone(phase))} className="min-h-11 rounded-xl border text-xs font-bold dark:border-gh-border">Edit phase</button><button type="button" onClick={() => setConfirm({ type: 'phase', id: phase.id })} className="min-h-11 rounded-xl border border-red-200 text-xs font-bold text-red-600">Delete</button></div>}</MobileCard>)}{canWrite && <MobileFAB label="Add phase" extended onClick={() => setPhaseEditor({ name: '', color: '#6366f1', icon: '📋' })}/>}<MobileBottomSheet open={Boolean(phaseDetail)} onClose={() => setPhaseDetail(null)} title="Phase detail"><PhaseDetailContent phase={phaseDetail}/></MobileBottomSheet><MobileBottomSheet open={Boolean(phaseEditor)} onClose={() => setPhaseEditor(null)} title={phaseEditor?.id ? 'Edit phase' : 'Add phase'} footer={<MobileStickyActions><button form="m9-phase-form" className="min-h-11 flex-1 rounded-xl bg-blue-600 font-bold text-white">Apply local change</button></MobileStickyActions>}><form id="m9-phase-form" onSubmit={savePhase} className="space-y-4"><MobileFormSection title="Phase details">{field('Name', phaseEditor?.name, (value) => setPhaseEditor((current) => ({ ...current, name: value })))}{field('Icon', phaseEditor?.icon, (value) => setPhaseEditor((current) => ({ ...current, icon: value })))}{field('Colour', phaseEditor?.color, (value) => setPhaseEditor((current) => ({ ...current, color: value })), 'color')}</MobileFormSection></form></MobileBottomSheet><MobileBottomSheet open={Boolean(taskEditor)} onClose={() => setTaskEditor(null)} title={taskEditor?.task?.id ? 'Activity details' : 'Add activity'} footer={canWrite ? <MobileStickyActions><button form="m9-task-form" className="min-h-11 flex-1 rounded-xl bg-blue-600 font-bold text-white">Apply local change</button></MobileStickyActions> : null}><form id="m9-task-form" onSubmit={saveTask} className="space-y-4"><MobileFormSection title="Schedule activity">{field('Name', taskEditor?.task?.name, (value) => setTaskEditor((current) => ({ ...current, task: { ...current.task, name: value } })), 'text', !canWrite)}<MobileDatePicker label="Start" disabled={!canWrite} value={taskEditor?.task?.start || ''} onChange={(event) => setTaskEditor((current) => ({ ...current, task: { ...current.task, start: event.target.value } }))}/><MobileDatePicker label="Finish" disabled={!canWrite} value={taskEditor?.task?.end || ''} onChange={(event) => setTaskEditor((current) => ({ ...current, task: { ...current.task, end: event.target.value } }))}/>{field('Progress %', taskEditor?.task?.progress, (value) => setTaskEditor((current) => ({ ...current, task: { ...current.task, progress: Math.max(0, Math.min(100, Number(value))) } })), 'number', !canWrite)}<label className="flex min-h-11 items-center gap-2 text-xs font-semibold"><input type="checkbox" disabled={!canWrite} checked={Boolean(taskEditor?.task?.critical)} onChange={(event) => setTaskEditor((current) => ({ ...current, task: { ...current.task, critical: event.target.checked } }))}/>High priority</label><label className="flex min-h-11 items-center gap-2 text-xs font-semibold"><input type="checkbox" disabled={!canWrite} checked={Boolean(taskEditor?.task?.milestone)} onChange={(event) => setTaskEditor((current) => ({ ...current, task: { ...current.task, milestone: event.target.checked } }))}/>Key deliverable</label>{canWrite && taskEditor?.task?.id && <button type="button" onClick={() => { setConfirm({ type: 'task', id: taskEditor.task.id }); setTaskEditor(null); }} className="min-h-11 w-full rounded-xl border border-red-200 text-sm font-bold text-red-600">Delete activity</button>}</MobileFormSection></form></MobileBottomSheet><MobileBottomSheet open={aiState !== 'idle'} onClose={() => { guard.current.invalidate(projectId); setAiState('idle'); }} title="AI Schedule Insights"><p className="mb-3 rounded-xl bg-violet-50 p-3 text-xs text-violet-800 dark:bg-violet-950/30 dark:text-violet-200">AI output is advisory. Verify schedule recommendations before acting.</p>{aiState === 'loading' ? <p role="status">Analysing schedule…</p> : aiState === 'error' ? <MobileEmptyState title="Insights unavailable" description={aiError} action={<button type="button" onClick={loadInsights} className="min-h-11 rounded-xl bg-violet-600 px-4 font-bold text-white">Retry</button>}/> : <div className="space-y-2">{(insights || []).map((item, index) => <MobileCard key={index}><b className="text-sm">{item.title || `Insight ${index + 1}`}</b><p className="mt-1 text-xs text-gray-600 dark:text-gh-muted">{item.body || item.message || String(item)}</p></MobileCard>)}</div>}</MobileBottomSheet><MobileConfirmModal open={Boolean(confirm)} onClose={() => setConfirm(null)} onConfirm={remove} danger title={`Delete ${confirm?.type || 'item'}`} message="This removes only the local planning item; no ERP record is changed."/></div>;
}

function MaterialWorkspace({ projectId }) {
    const [selected, setSelected] = useState(MATERIALS.map((item) => item.id)); const [filterOpen, setFilterOpen] = useState(false); const data = useMemo(() => Object.fromEntries(MATERIALS.map((material, materialIndex) => [material.id, MONTHS.map((month, monthIndex) => { const planned = Math.max(0, Math.round((materialIndex + 1) * 18 + Math.sin(monthIndex / 2) * 10 + monthIndex * 2)); const actual = Math.max(0, Math.round(planned * (0.82 + ((materialIndex * 7 + monthIndex * 3) % 31) / 100))); return { month, planned, actual }; })])), [projectId]);
    const rows = MATERIALS.filter((item) => selected.includes(item.id)).map((material) => { const values = data[material.id]; const planned = values.reduce((sum, item) => sum + item.planned, 0); const actual = values.reduce((sum, item) => sum + item.actual, 0); return { ...material, values, planned, actual, variance: actual - planned, cost: actual * material.rate }; }); const total = rows.reduce((sum, row) => sum + row.cost, 0);
    return <div data-m9-view="material-histogram" className="space-y-3 px-4 pb-28"><MobilePageHeader title="Material Histogram" subtitle="FY2026 source demo analytics"/><LocalNotice>This is generated frontend demo data, not live procurement, inventory, or ERP consumption.</LocalNotice><div className="grid grid-cols-2 gap-2"><MobileStatCard label="Materials" value={rows.length} icon={Package}/><MobileStatCard label="Demo actual cost" value={formatMoney(total)} tone="amber"/></div><div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => setFilterOpen(true)} className="min-h-11 rounded-xl border text-xs font-bold dark:border-gh-border"><Filter size={15} className="mr-1 inline"/>Materials</button><button type="button" onClick={() => downloadCsv('Material_Histogram_FY2026.csv', ['Material','Month','Planned','Demo actual'], rows.flatMap((row) => row.values.map((item) => [row.name, item.month, item.planned, item.actual])))} className="min-h-11 rounded-xl border text-xs font-bold dark:border-gh-border"><Download size={15} className="mr-1 inline"/>Export CSV</button></div>{rows.map((row) => <MobileCard key={row.id}><div className="flex justify-between gap-3"><div><h3 className="text-sm font-black">{row.name}</h3><p className="text-xs text-gray-500">{row.unit} · fixed demo rate {formatMoney(row.rate)}</p></div><b className={row.variance > 0 ? 'text-red-600' : 'text-emerald-600'}>{row.variance > 0 ? '+' : ''}{row.variance}</b></div><div className="mt-3 grid grid-cols-3 gap-2 text-center text-[11px]"><div><b className="block text-sm">{row.planned}</b>Planned</div><div><b className="block text-sm">{row.actual}</b>Demo actual</div><div><b className="block text-sm">{formatMoney(row.cost)}</b>Cost</div></div><div className="mt-3 flex h-24 items-end gap-1" aria-label={`${row.name} monthly planned and actual bars`}>{row.values.map((item) => <div key={item.month} className="flex min-w-0 flex-1 items-end gap-px"><span className="w-1/2 rounded-t bg-blue-400" style={{ height: `${Math.max(5, item.planned)}%` }}/><span className="w-1/2 rounded-t bg-emerald-400" style={{ height: `${Math.max(5, item.actual)}%` }}/></div>)}</div></MobileCard>)}<MobileFilterSheet open={filterOpen} onClose={() => setFilterOpen(false)} onReset={() => setSelected(MATERIALS.map((item) => item.id))} onApply={() => setFilterOpen(false)} title="Material filter">{MATERIALS.map((material) => <label key={material.id} className="flex min-h-11 items-center gap-3 rounded-xl px-2"><input type="checkbox" checked={selected.includes(material.id)} onChange={() => setSelected((current) => current.includes(material.id) ? current.filter((id) => id !== material.id) : [...current, material.id])}/>{material.name}</label>)}</MobileFilterSheet></div>;
}

function ManpowerWorkspace({ projectId, canWrite, searchParams, setSearchParams }) {
    const view = resolveManpowerView(searchParams.get('mpView'));
    const [phases, setPhases] = useState(() => clone(MANPOWER_PHASES));
    const [editor, setEditor] = useState(null);
    const [allocation, setAllocation] = useState(null);
    const [importOpen, setImportOpen] = useState(false);
    const [selectedTrades, setSelectedTrades] = useState(() => TRADES.map((trade) => trade.id));
    const [filterOpen, setFilterOpen] = useState(false);
    useEffect(() => { setPhases(clone(MANPOWER_PHASES)); setEditor(null); setAllocation(null); setImportOpen(false); setFilterOpen(false); setSelectedTrades(TRADES.map((trade) => trade.id)); }, [projectId]);
    const tasks = phases.flatMap((phase) => phase.tasks.map((task) => ({ ...task, phaseId: phase.id, phaseName: phase.name })));
    const workers = tasks.reduce((sum, task) => sum + Object.values(task.manpower || {}).reduce((sub, value) => sub + Number(value || 0), 0), 0);
    const manDays = tasks.reduce((sum, task) => sum + durationDays(task.start, task.end) * Object.values(task.manpower || {}).reduce((sub, value) => sub + Number(value || 0), 0), 0);
    const setView = (next) => setSearchParams(updateSearch(searchParams, { mpView: next === 'histogram' ? null : next }));
    const savePhase = (event) => { event.preventDefault(); if (!canWrite || !editor?.name?.trim()) return; setPhases((current) => editor.id ? current.map((phase) => phase.id === editor.id ? editor : phase) : [...current, { ...editor, id: makeLocalId('mp-phase'), tasks: [] }]); setEditor(null); };
    const saveAllocation = () => { if (!canWrite || !allocation) return; setPhases((current) => current.map((phase) => ({ ...phase, tasks: phase.tasks.map((task) => task.id === allocation.id ? allocation : task) }))); setAllocation(null); };
    const importProjectPlan = () => { if (!canWrite) return; const imports = SOURCE_PHASES.slice(0, 2).map((phase) => ({ id: makeLocalId('import'), name: phase.name, tasks: phase.activities.map((task) => ({ id: makeLocalId('import-task'), name: task.name, start: task.start, end: task.end, manpower: {} })) })); setPhases((current) => [...current, ...imports]); setImportOpen(false); };
    return <div data-m9-view="manpower-histogram" className="space-y-3 px-4 pb-28">
        <MobilePageHeader title="Manpower" subtitle="Local planning and estimated FY2026 analytics"/>
        <LocalNotice>Planned headcount and estimated “actual” values are local demo calculations. They are not attendance, HRM, payroll, or live workforce records.</LocalNotice>
        <MobileTabs segmented label="Manpower views" value={view} onChange={setView} items={[{ value:'histogram', label:'Histogram' },{ value:'planning', label:'Planning' }]}/>
        <div className="grid grid-cols-2 gap-2"><MobileStatCard label="Task allocations" value={tasks.length} icon={Users}/><MobileStatCard label="Planned man-days" value={manDays.toLocaleString('en-IN')} tone="green"/><MobileStatCard label="Planned workers" value={workers}/><MobileStatCard label="Daily trade rates" value={TRADES.length} tone="amber"/></div>
        {view === 'histogram' ? <><div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => setFilterOpen(true)} className="min-h-11 rounded-xl border text-xs font-bold dark:border-gh-border"><Filter size={15} className="mr-1 inline"/>Trades</button><button type="button" onClick={() => downloadCsv('Manpower_Histogram_FY2026.csv', ['Trade','Planned workers','Demo estimated actual','Daily rate'], TRADES.filter((trade) => selectedTrades.includes(trade.id)).map((trade, index) => { const planned = tasks.reduce((sum, task) => sum + Number(task.manpower?.[trade.id] || 0), 0); return [trade.name, planned, Math.max(0, Math.round(planned * (0.86 + (index % 4) * 0.04))), trade.rate]; }))} className="min-h-11 rounded-xl border text-xs font-bold dark:border-gh-border"><Download size={15} className="mr-1 inline"/>Export CSV</button></div><MobileCard><h3 className="text-sm font-black">Trade composition</h3><div className="mt-3 space-y-3">{TRADES.filter((trade) => selectedTrades.includes(trade.id)).map((trade, index) => { const count = tasks.reduce((sum, task) => sum + Number(task.manpower?.[trade.id] || 0), 0); const estimated = Math.max(0, Math.round(count * (0.86 + (index % 4) * 0.04))); return <div key={trade.id}><div className="flex justify-between gap-3 text-xs"><b>{trade.name}</b><span className="text-right">{count} planned · {estimated} demo estimated actual<br/>{formatMoney(trade.rate)}/day</span></div><div className="mt-1 flex h-2 gap-1"><span className="block h-full rounded bg-blue-600" style={{ width: `${Math.min(100, count * 2)}%` }}/><span className="block h-full rounded bg-emerald-500" style={{ width: `${Math.min(100, estimated * 2)}%` }}/></div></div>; })}</div></MobileCard><MobileFilterSheet open={filterOpen} onClose={() => setFilterOpen(false)} onReset={() => setSelectedTrades(TRADES.map((trade) => trade.id))} onApply={() => setFilterOpen(false)} title="Trade filter">{TRADES.map((trade) => <label key={trade.id} className="flex min-h-11 items-center gap-3 rounded-xl px-2"><input type="checkbox" checked={selectedTrades.includes(trade.id)} onChange={() => setSelectedTrades((current) => current.includes(trade.id) ? current.filter((id) => id !== trade.id) : [...current, trade.id])}/>{trade.name}</label>)}</MobileFilterSheet></> : <div className="space-y-3"><div className="grid grid-cols-2 gap-2">{canWrite && <><button type="button" onClick={() => setImportOpen(true)} className="min-h-11 rounded-xl border text-xs font-bold dark:border-gh-border">Import Project Plan</button><button type="button" onClick={() => setEditor({ name:'', tasks:[] })} className="min-h-11 rounded-xl bg-blue-600 text-xs font-bold text-white">Add phase</button></>}</div>{phases.map((phase) => <MobileCard key={phase.id}><button type="button" onClick={() => canWrite && setEditor(clone(phase))} className="min-h-11 w-full text-left"><h3 className="text-sm font-black">{phase.name}</h3><p className="text-xs text-gray-500">{phase.tasks.length} planned tasks</p></button><div className="mt-2 space-y-2">{phase.tasks.map((task) => { const count = Object.values(task.manpower || {}).reduce((sum, value) => sum + Number(value), 0); return <button type="button" key={task.id} onClick={() => setAllocation(clone(task))} className="min-h-11 w-full rounded-xl bg-gray-50 p-3 text-left dark:bg-gh-hover"><b className="text-xs">{task.name}</b><p className="text-[11px] text-gray-500">{task.start} → {task.end} · {count} workers · {durationDays(task.start, task.end) * count} man-days</p></button>; })}</div></MobileCard>)}</div>}
        <MobileBottomSheet open={Boolean(editor)} onClose={() => setEditor(null)} title={editor?.id ? 'Edit manpower phase' : 'Add manpower phase'} footer={<MobileStickyActions><button form="mp-phase" className="min-h-11 flex-1 rounded-xl bg-blue-600 font-bold text-white">Apply local change</button></MobileStickyActions>}><form id="mp-phase" onSubmit={savePhase}><MobileFormSection title="Phase">{field('Name', editor?.name, (value) => setEditor((current) => ({ ...current, name:value })))}</MobileFormSection></form></MobileBottomSheet>
        <MobileBottomSheet open={Boolean(allocation)} onClose={() => setAllocation(null)} title="Trade allocation" footer={canWrite ? <MobileStickyActions><button type="button" onClick={saveAllocation} className="min-h-11 flex-1 rounded-xl bg-blue-600 font-bold text-white">Apply allocation</button></MobileStickyActions> : null}><div className="space-y-3">{TRADES.map((trade) => <label key={trade.id} className="flex min-h-12 items-center justify-between gap-3 rounded-xl border p-3 text-xs dark:border-gh-border"><span><b>{trade.name}</b><span className="block text-gray-500">{formatMoney(trade.rate)}/day</span></span><input type="number" min="0" disabled={!canWrite} value={allocation?.manpower?.[trade.id] || 0} onChange={(event) => setAllocation((current) => ({ ...current, manpower:{ ...current.manpower, [trade.id]:Math.max(0, Number(event.target.value)) } }))} className="h-11 w-20 rounded-xl border bg-transparent px-2 text-center dark:border-gh-border"/></label>)}</div></MobileBottomSheet>
        <MobileBottomSheet open={importOpen} onClose={() => setImportOpen(false)} title="Import from Project Plan" footer={<MobileStickyActions><button type="button" onClick={importProjectPlan} className="min-h-11 flex-1 rounded-xl bg-blue-600 font-bold text-white">Import selected source phases</button></MobileStickyActions>}><p className="text-sm">Import the first two source schedule phases and their tasks. Imported manpower allocations start empty.</p></MobileBottomSheet>
    </div>;
}

function LogisticWorkspace({ projectId, canWrite }) {
    const [tab, setTab] = useState('deliveries'); const [deliveries, setDeliveries] = useState(() => clone(DELIVERIES)); const [equipment, setEquipment] = useState(() => clone(EQUIPMENT)); const [filter, setFilter] = useState('all'); const [editor, setEditor] = useState(null); const [detail, setDetail] = useState(null); const [confirm, setConfirm] = useState(null); const [summaryOpen, setSummaryOpen] = useState(false);
    useEffect(() => { setDeliveries(clone(DELIVERIES)); setEquipment(clone(EQUIPMENT)); setEditor(null); setDetail(null); setConfirm(null); }, [projectId]); const visible = filter === 'all' ? deliveries : deliveries.filter((row) => row.status === filter);
    const save = (event) => { event.preventDefault(); if (!canWrite || !editor) return; const [rows, setter] = editor.kind === 'delivery' ? [deliveries, setDeliveries] : [equipment, setEquipment]; setter(rows.some((row) => row.id === editor.item.id) ? rows.map((row) => row.id === editor.item.id ? editor.item : row) : [...rows, { ...editor.item, id: makeLocalId(editor.kind) }]); setEditor(null); };
    const remove = () => { if (confirm.kind === 'delivery') setDeliveries((current) => current.filter((row) => row.id !== confirm.id)); else setEquipment((current) => current.filter((row) => row.id !== confirm.id)); setConfirm(null); setDetail(null); };
    return <div data-m9-view="logistic-plan" className="space-y-3 px-4 pb-28"><MobilePageHeader title="Logistic Plan" subtitle="Local delivery and equipment plan" actions={<div className="flex gap-2"><button type="button" aria-label="Export logistics CSV" onClick={() => tab === 'deliveries' ? downloadCsv('Logistic_Deliveries.csv', ['Material','Vendor','PO','Quantity','Expected','Actual','Status'], deliveries.map((row) => [row.material,VENDORS.find((vendor) => vendor.id === row.vendor)?.name || '',row.po,row.qty,row.expected,row.actual,row.status])) : downloadCsv('Logistic_Equipment.csv', ['Equipment','Type','Assigned from','Assigned to','Utilisation','Status','Rate per day'], equipment.map((row) => [row.name,row.type,row.assignedFrom,row.assignedTo,row.utilization,row.status,row.rate]))} className="min-h-11 min-w-11 rounded-xl border px-3 text-xs font-bold dark:border-gh-border"><Download size={16}/></button><button type="button" onClick={() => setSummaryOpen(true)} className="min-h-11 rounded-xl border px-3 text-xs font-bold dark:border-gh-border">Summary</button></div>}/><LocalNotice>Changes and the logistics summary are frontend-local. The summary is a deterministic heuristic, not model-generated AI.</LocalNotice><MobileTabs segmented value={tab} onChange={setTab} items={[{ value:'deliveries', label:'Deliveries', count:deliveries.length },{ value:'equipment', label:'Equipment', count:equipment.length }]}/>{tab === 'deliveries' ? <><MobileSelect label="Status filter" value={filter} onChange={(event) => setFilter(event.target.value)} options={['all','delivered','intransit','pending','delayed'].map((value) => ({ value, label:value === 'intransit' ? 'In Transit' : value[0].toUpperCase()+value.slice(1) }))}/><div className="grid grid-cols-2 gap-2"><MobileStatCard label="Delivered" value={deliveries.filter((row) => row.status === 'delivered').length} icon={Truck} tone="green"/><MobileStatCard label="Delayed" value={deliveries.filter((row) => row.status === 'delayed').length} icon={AlertTriangle} tone="red"/></div>{visible.map((row) => <MobileEntityCard key={row.id} title={row.material} subtitle={`${VENDORS.find((vendor) => vendor.id === row.vendor)?.name || 'Unknown vendor'} · ${row.qty}`} meta={`${row.po} · expected ${row.expected} · ${row.status}`} onClick={() => setDetail({ kind:'delivery', item:row })}/>)}</> : <>{equipment.map((row) => <MobileEntityCard key={row.id} title={row.name} subtitle={`${row.type} · ${row.utilization}% utilisation`} meta={`${row.assignedFrom} → ${row.assignedTo} · ${formatMoney(row.rate)}/day`} onClick={() => setDetail({ kind:'equipment', item:row })}/>)}</>}{canWrite && <MobileFAB label={tab === 'deliveries' ? 'Add delivery' : 'Add equipment'} extended onClick={() => setEditor(tab === 'deliveries' ? { kind:'delivery', item:{ material:'', vendor:'v1', po:'', qty:'', expected:'', actual:'', status:'pending' } } : { kind:'equipment', item:{ name:'', type:'', assignedFrom:'', assignedTo:'', utilization:0, status:'active', rate:0 } })}/>}<MobileBottomSheet open={Boolean(detail)} onClose={() => setDetail(null)} title={detail?.kind === 'delivery' ? 'Delivery detail' : 'Equipment detail'} footer={canWrite ? <MobileStickyActions><button type="button" onClick={() => { setEditor({ kind:detail.kind, item:clone(detail.item) }); setDetail(null); }} className="min-h-11 flex-1 rounded-xl bg-blue-600 font-bold text-white">Edit local item</button><button type="button" onClick={() => setConfirm({ kind:detail.kind, id:detail.item.id })} className="min-h-11 rounded-xl border border-red-300 px-4 font-bold text-red-600">Delete</button></MobileStickyActions> : null}>{detail && <dl className="space-y-2 text-sm">{Object.entries(detail.item).map(([key,value]) => <div key={key} className="rounded-xl bg-gray-50 p-3 dark:bg-gh-hover"><dt className="text-[10px] font-bold uppercase text-gray-500">{key}</dt><dd>{String(value || '—')}</dd></div>)}</dl>}</MobileBottomSheet><MobileBottomSheet open={Boolean(editor)} onClose={() => setEditor(null)} title={editor?.item?.id ? `Edit ${editor?.kind}` : `Add ${editor?.kind}`} footer={<MobileStickyActions><button form="logistic-form" className="min-h-11 flex-1 rounded-xl bg-blue-600 font-bold text-white">Apply local change</button></MobileStickyActions>}><form id="logistic-form" onSubmit={save}><MobileFormSection title="Details">{editor?.kind === 'delivery' ? <>{field('Material', editor.item.material, (value) => setEditor((current) => ({ ...current,item:{...current.item,material:value} })))}<MobileSelect label="Vendor" value={editor.item.vendor} onChange={(event) => setEditor((current) => ({...current,item:{...current.item,vendor:event.target.value}}))} options={VENDORS.map((vendor) => ({value:vendor.id,label:`${vendor.name} · ${vendor.city}`}))}/>{field('PO', editor.item.po, (value) => setEditor((current) => ({...current,item:{...current.item,po:value}})))}{field('Quantity', editor.item.qty, (value) => setEditor((current) => ({...current,item:{...current.item,qty:value}})))}<MobileDatePicker label="Expected" value={editor.item.expected} onChange={(event) => setEditor((current) => ({...current,item:{...current.item,expected:event.target.value}}))}/><MobileDatePicker label="Actual" value={editor.item.actual} onChange={(event)=>setEditor((current)=>({...current,item:{...current.item,actual:event.target.value}}))}/><MobileSelect label="Status" value={editor.item.status} onChange={(event)=>setEditor((current)=>({...current,item:{...current.item,status:event.target.value}}))} options={['delivered','intransit','pending','delayed'].map((value)=>({value,label:value}))}/></> : <>{field('Name',editor?.item?.name,(value)=>setEditor((current)=>({...current,item:{...current.item,name:value}})))}{field('Type',editor?.item?.type,(value)=>setEditor((current)=>({...current,item:{...current.item,type:value}})))}<MobileDatePicker label="Assigned from" value={editor?.item?.assignedFrom||''} onChange={(event)=>setEditor((current)=>({...current,item:{...current.item,assignedFrom:event.target.value}}))}/><MobileDatePicker label="Assigned to" value={editor?.item?.assignedTo||''} onChange={(event)=>setEditor((current)=>({...current,item:{...current.item,assignedTo:event.target.value}}))}/>{field('Rate/day',editor?.item?.rate,(value)=>setEditor((current)=>({...current,item:{...current.item,rate:Number(value)}})),'number')}{field('Utilisation %',editor?.item?.utilization,(value)=>setEditor((current)=>({...current,item:{...current.item,utilization:Number(value)}})),'number')}<MobileSelect label="Status" value={editor?.item?.status||'active'} onChange={(event)=>setEditor((current)=>({...current,item:{...current.item,status:event.target.value}}))} options={[{value:'active',label:'Active'},{value:'returned',label:'Returned'}]}/></>}</MobileFormSection></form></MobileBottomSheet><MobileBottomSheet open={summaryOpen} onClose={()=>setSummaryOpen(false)} title="Local Logistics Summary"><div className="space-y-3 text-sm"><p>{deliveries.filter((row)=>row.status==='delayed').length} delayed deliveries need attention.</p><p>{equipment.filter((row)=>row.status==='active').length} equipment assignments are active.</p><p>On-time delivery rate: {Math.round(deliveries.filter((row)=>row.status==='delivered'&&row.actual<=row.expected).length/Math.max(1,deliveries.filter((row)=>row.status==='delivered').length)*100)}%.</p></div></MobileBottomSheet><MobileConfirmModal open={Boolean(confirm)} onClose={()=>setConfirm(null)} onConfirm={remove} danger title="Delete local plan item" message="This changes only the current frontend planning view."/></div>;
}

function HindranceWorkspace({ projectId, canWrite }) {
    const [rows,setRows]=useState(()=>clone(HINDRANCES)); const [editor,setEditor]=useState(null); const [detail,setDetail]=useState(null); const [confirm,setConfirm]=useState(null); useEffect(()=>{setRows(clone(HINDRANCES));setEditor(null);setDetail(null);setConfirm(null);},[projectId]); const save=(event)=>{event.preventDefault();if(!canWrite||!editor?.description?.trim())return;setRows((current)=>editor.id?current.map((row)=>row.id===editor.id?editor:row):[...current,{...editor,id:makeLocalId('hindrance')}]);setEditor(null);}; const remove=()=>{setRows((current)=>current.filter((row)=>row.id!==confirm));setConfirm(null);setDetail(null);};
    return <div data-m9-view="hindrance-report" className="space-y-3 px-4 pb-28"><MobilePageHeader title="Events / Hindrance Report" subtitle="Local schedule variance register"/><LocalNotice>Hindrance edits are local to this frontend workspace and are not persisted to the ERP.</LocalNotice>{rows.map((row)=><button type="button" key={row.id} onClick={()=>setDetail(row)} className="w-full text-left"><MobileCard><div className="flex justify-between gap-3"><h3 className="text-sm font-black">{row.description}</h3><span className="rounded-full bg-red-50 px-2 py-1 text-[10px] font-bold text-red-700 dark:bg-red-950/30">Start {dateDiff(row.actualStart,row.plannedStart)>0?'+':''}{dateDiff(row.actualStart,row.plannedStart)}d</span></div><p className="mt-2 text-xs text-gray-500">Planned {row.plannedStart} → {row.plannedFinish}</p><p className="text-xs text-gray-500">Actual {row.actualStart||'—'} → {row.actualFinish||'—'} · finish variance {dateDiff(row.actualFinish,row.plannedFinish)}d</p></MobileCard></button>)}{canWrite&&<MobileFAB label="Add hindrance" extended onClick={()=>setEditor({description:'',plannedStart:'',plannedFinish:'',plannedDays:0,actualStart:'',actualFinish:'',actualDays:0,responsibleStart:'',remarksStart:'',responsibleFinish:'',remarksEnd:''})}/>}<MobileBottomSheet open={Boolean(detail)} onClose={()=>setDetail(null)} title="Hindrance detail" footer={canWrite?<MobileStickyActions><button type="button" onClick={()=>{setEditor(clone(detail));setDetail(null);}} className="min-h-11 flex-1 rounded-xl bg-blue-600 font-bold text-white">Edit</button><button type="button" onClick={()=>setConfirm(detail.id)} className="min-h-11 rounded-xl border border-red-300 px-4 font-bold text-red-600">Delete</button></MobileStickyActions>:null}>{detail&&<dl className="space-y-2 text-sm">{Object.entries(detail).filter(([key])=>key!=='id').map(([key,value])=><div key={key} className="rounded-xl bg-gray-50 p-3 dark:bg-gh-hover"><dt className="text-[10px] font-bold uppercase text-gray-500">{key.replace(/([A-Z])/g,' $1')}</dt><dd>{String(value||'—')}</dd></div>)}<div className="rounded-xl bg-red-50 p-3 text-red-700 dark:bg-red-950/30">Computed delays: start {dateDiff(detail.actualStart,detail.plannedStart)}d · finish {dateDiff(detail.actualFinish,detail.plannedFinish)}d</div></dl>}</MobileBottomSheet><MobileBottomSheet open={Boolean(editor)} onClose={()=>setEditor(null)} title={editor?.id?'Edit hindrance':'Add hindrance'} footer={<MobileStickyActions><button form="hindrance-form" className="min-h-11 flex-1 rounded-xl bg-blue-600 font-bold text-white">Apply local change</button></MobileStickyActions>}><form id="hindrance-form" onSubmit={save}><MobileFormSection title="Schedule">{field('Description',editor?.description,(value)=>setEditor((current)=>({...current,description:value})))}<MobileDatePicker label="Planned start" value={editor?.plannedStart||''} onChange={(event)=>setEditor((current)=>({...current,plannedStart:event.target.value}))}/><MobileDatePicker label="Planned finish" value={editor?.plannedFinish||''} onChange={(event)=>setEditor((current)=>({...current,plannedFinish:event.target.value}))}/>{field('Planned days',editor?.plannedDays,(value)=>setEditor((current)=>({...current,plannedDays:Number(value)})),'number')}<MobileDatePicker label="Actual start" value={editor?.actualStart||''} onChange={(event)=>setEditor((current)=>({...current,actualStart:event.target.value}))}/><MobileDatePicker label="Actual finish" value={editor?.actualFinish||''} onChange={(event)=>setEditor((current)=>({...current,actualFinish:event.target.value}))}/>{field('Actual days',editor?.actualDays,(value)=>setEditor((current)=>({...current,actualDays:Number(value)})),'number')}{field('Responsible (start)',editor?.responsibleStart,(value)=>setEditor((current)=>({...current,responsibleStart:value})))}{field('Remarks (start)',editor?.remarksStart,(value)=>setEditor((current)=>({...current,remarksStart:value})))}{field('Responsible (finish)',editor?.responsibleFinish,(value)=>setEditor((current)=>({...current,responsibleFinish:value})))}{field('Remarks (finish)',editor?.remarksEnd,(value)=>setEditor((current)=>({...current,remarksEnd:value})))}<p className="text-xs text-gray-500">Computed delay (read-only): start {dateDiff(editor?.actualStart,editor?.plannedStart)}d · finish {dateDiff(editor?.actualFinish,editor?.plannedFinish)}d</p></MobileFormSection></form></MobileBottomSheet><MobileConfirmModal open={Boolean(confirm)} onClose={()=>setConfirm(null)} onConfirm={remove} danger title="Delete hindrance" message="This removes only the local report row."/></div>;
}

const HUB_ITEMS=[{id:'project-planning',title:'Project Planning & Bar Chart',description:'Phases, activity dates, progress and schedule insights.',icon:BarChart3},{id:'logistic-plan',title:'Logistic Plan',description:'Local deliveries, equipment and operational summary.',icon:Truck},{id:'manpower-histogram',title:'Manpower Histogram',description:'Local trade planning and estimated resource analytics.',icon:Users},{id:'material-histogram',title:'Material Histogram',description:'FY2026 generated material plan demo.',icon:Package},{id:'hindrance-report',title:'Events / Hindrance Report',description:'Local schedule variance and responsibility register.',icon:AlertTriangle},{id:'budget',title:'Budget',description:'Open the Contracts-owned local budget workspace.',icon:FileStack}];
export default function MobileProjectPlanning({ projectId, canWrite, services={} }) { const [searchParams,setSearchParams]=useSearchParams(); const report=resolvePlanningReport(searchParams.get('report')); useEffect(()=>{const requested=searchParams.get('report');if(requested&&!['project-planning','logistic-plan','manpower-histogram','material-histogram','hindrance-report','budget'].includes(requested))setSearchParams(updateSearch(searchParams,{report:null}),{replace:true});if(requested==='budget')setSearchParams(updateSearch(searchParams,{tab:'Contracts',report:'budget',section:null}),{replace:true});},[searchParams,setSearchParams]); const open=(id)=>{if(id==='budget'){setSearchParams(updateSearch(searchParams,{tab:'Contracts',report:'budget',section:null}));return;}setSearchParams(updateSearch(searchParams,{report:id,section:null}));}; const back=()=>setSearchParams(updateSearch(searchParams,{report:null,mpView:null})); if(report==='project-planning')return <><button type="button" onClick={back} className="mx-4 min-h-11 text-sm font-bold text-blue-600">← Planning hub</button><ScheduleWorkspace projectId={projectId} canWrite={canWrite} aiService={services.ai}/></>; if(report==='material-histogram')return <><button type="button" onClick={back} className="mx-4 min-h-11 text-sm font-bold text-blue-600">← Planning hub</button><MaterialWorkspace projectId={projectId}/></>; if(report==='manpower-histogram')return <><button type="button" onClick={back} className="mx-4 min-h-11 text-sm font-bold text-blue-600">← Planning hub</button><ManpowerWorkspace projectId={projectId} canWrite={canWrite} searchParams={searchParams} setSearchParams={setSearchParams}/></>; if(report==='logistic-plan')return <><button type="button" onClick={back} className="mx-4 min-h-11 text-sm font-bold text-blue-600">← Planning hub</button><LogisticWorkspace projectId={projectId} canWrite={canWrite}/></>; if(report==='hindrance-report')return <><button type="button" onClick={back} className="mx-4 min-h-11 text-sm font-bold text-blue-600">← Planning hub</button><HindranceWorkspace projectId={projectId} canWrite={canWrite}/></>; if(report==='budget')return null; return <div data-m9-view="planning-hub" className="space-y-3 px-4 pb-28"><MobilePageHeader title="Planning" subtitle="Source-backed project planning workspaces"/>{HUB_ITEMS.map((item)=><MobileEntityCard key={item.id} icon={item.icon} title={item.title} subtitle={item.description} meta={item.id==='budget'?'Owned by Contracts':item.id==='material-histogram'?'Read-only demo analytics':'Frontend-local planning'} onClick={()=>open(item.id)}/>)}</div>; }
